module.exports = function (RED) {
    function IgnoreNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;

        node.event_type = config.event_type;
        node.location = config.location;

        node.on('input', function (msg, send, done) {
            // 判断是否符合要忽略的事件类型和位置
            const matchType = msg.eventType === node.event_type;
            const matchLocation = RED.util.getMessageProperty(msg, 'location') === node.location;

            if (matchType && matchLocation) {
                // 不发送，表示“忽略”
                node.status({ fill: "grey", shape: "ring", text: "Ignored" });
                done();
            } else {
                send(msg); // 传递下去
                done();
            }
        });
    }

    RED.nodes.registerType("Ignore", IgnoreNode);
};